.cmp-accordion__header{margin:0}
.cmp-accordion__button{display:block;width:100%;text-align:left}
.cmp-accordion__panel--hidden{display:none}
.cmp-accordion__panel--expanded{display:block}
.cmp-tabs__tablist{display:flex;flex-wrap:wrap;padding-left:0;list-style:none}
.cmp-tabs__tab{box-sizing:border-box;border-bottom:1px solid transparent;padding:.5rem 1rem;cursor:pointer}
.cmp-tabs__tab--active{border-color:inherit}
.cmp-tabs__tabpanel{display:none}
.cmp-tabs__tabpanel--active{display:block}
.cmp-carousel__content{position:relative}
.cmp-carousel__item{display:none}
.cmp-carousel__item--active{display:block}
.cmp-carousel__action{-webkit-appearance:none;-moz-appearance:none;appearance:none}
.cmp-carousel__indicators{display:flex;flex-wrap:wrap;justify-content:center;margin:0;padding:0;list-style:none}
.cmp-carousel__indicator{position:relative;flex:0 1 auto;width:10px;height:10px;margin:0 7px;border-radius:50%;font-size:0;text-indent:-3000px;background-color:rgba(0,0,0,0.5)}
.cmp-carousel__indicator--active{background-color:rgba(0,0,0,0.8)}
.cmp-image__image{width:100%;height:auto}
.cmp-breadcrumb{display:inline-block;list-style:none;padding:0}
.cmp-breadcrumb__item{display:inline-block;vertical-align:top}
.cmp-search{position:relative}
.cmp-search__field{position:relative;height:2rem}
.cmp-search__input{padding-left:2rem;padding-right:2rem;height:100%;width:100%}
.cmp-search__icon{display:block;position:absolute;left:.5rem;top:.5rem;background-image:url("data:image/svg+xml;base64,");background-size:contain;width:1rem;height:1rem;pointer-events:none}
.cmp-search__loading-indicator{display:none;position:absolute;top:.5rem;left:.5rem;border:3px solid #ccc;border-top-color:#333;border-radius:50%;width:1rem;height:1rem;animation:cmp-search__loading-indicator-spin 2s linear infinite}
@keyframes cmp-search__loading-indicator-spin{0{transform:rotate(0)}
100%{transform:rotate(360deg)}
}
.cmp-search__clear{display:none;margin:0;padding:0;border:0;background:transparent}
.cmp-search__clear-icon{position:absolute;top:.5rem;right:.5rem;background-image:url("data:image/svg+xml;base64,");background-size:contain;width:1rem;height:1rem}
.cmp-search__results{display:none;overflow-y:auto;min-width:100%;max-height:10rem;position:absolute;top:100%;left:0;z-index:999999;border:1px solid #ccc;background:#fff}
.cmp-search__item{display:block}
.cmp-search__item--is-focused{background-color:#ccc}
.cmp_search__info{height:20px;font-size:.875rem;font-style:italic}
.cmp-form-text .cmp-form-text__validation-message{visibility:hidden}
.cmp-form-text :invalid + .cmp-form-text__validation-message{visibility:visible}
.cmp-pdfviewer__content{height:500px}
.pdfviewer:not(.cq-Editable-dom) .cmp-pdfviewer__full-window-borderless{height:100vh;position:fixed;width:100vw;top:0;left:0;z-index:9999}
.pdfviewer.cq-Editable-dom .cmp-pdfviewer__full-window-borderless{height:500px}
.cmp-embed__youtube{position:relative;width:100%;height:0;padding-bottom:56.25%}
.cmp-embed__youtube-iframe{position:absolute;left:0;top:0;height:100%;width:100%}
